# Libraries
source("mounts/research/src/Rfunctions/library.R")

# Parameters
source("mounts/research/husdatalake/disease/scripts/AML/R/parameters")

# Paths — generated by the notebook's setup cell; edit config there, not here
source("/home/HUSTIETOALLAS/ext11670944/mounts/research/husdatalake/disease/scripts/AML_mutation_prediction/aml-mutation-prediction/data/eln/eln_run_config.R")

if (length(list.files(OUTPUT_DATA_DIR)) > 0) {
  stop(paste(
    "OUTPUT_DATA_DIR is not empty:", OUTPUT_DATA_DIR,
    "\nChange RUN_ID in the notebook config cell and rerun setup."
  ))
}

INPUT_DATA_FILES <- list.files(INPUT_DATA_DIR, pattern = "\\.csv$")
# -----------------------------------------------------------------------------------------------------------------------------------------

for (input_data_filename in INPUT_DATA_FILES) {
  
  output_filename <- sub("clinical_data", "eln", input_data_filename)
  
  # read original clinical data of the study cohort
  data <- read.csv(file.path(INPUT_DATA_DIR, input_data_filename), check.names=FALSE)
  
  # set empty strings to NA
  data[data == ""] <- NA
  
  # create new table where we gonna define new ELN classifications
  eln <- data
  
  # drop ELN1-columns from the read table just in case because we will generate these again
  eln <- eln[, !(colnames(eln) %in% c("ELN1_int", "ELN1_adv", "ELN1_fav", "ELN1"))]
  
  # define ELN-risk classifications
  # NOTE: The code below is adopted from `eln.R` with one expections: "abn_"-variables are not taken into account because these are missing
  eln = eln %>%
    mutate(
      ELN1_fav = ifelse(((!is.na(`RUNX1-RUNX1T1`) & `RUNX1-RUNX1T1`=="POS") | (!is.na(`CBFB-MYH11`) & `CBFB-MYH11`=="POS") | inv_16=="POS" | t_8_21=="POS" | t_16_16=="POS" | (NPM1=="POS" & FLT3_ITD!="POS")), 1, 0),
      ELN1_adv = ifelse(translocation3 == 1 |
                          translocation11 == 1 |
                          # (rowSums(across(one_of(contains("t_[[:print:]]*11")))) == 1 |
                          # rowSums(across(one_of(contains("t[[:print:]]*_3")))) == 1 |
                          (str_detect(fuus, "(?i)(KAT6A|KMT2A)") & str_detect(fuus, "(?i)(MLLT3)")) | 
                          (!is.na(`DEK-NUP214`) & `DEK-NUP214`=="POS") | 
                          (!is.na(`BCR-ABL`) & `BCR-ABL`=="POS") | 
                          (!is.na(`KAT6A-CREBBP`) & `KAT6A-CREBBP`=="POS") | 
                          (!is.na(`KMT2A-AFDN`) & `KMT2A-AFDN`=="POS") | 
                          (!is.na(`KMT2A-AFF1`) & `KMT2A-AFF1`=="POS") | 
                          (!is.na(`KMT2A-CBL`) & `KMT2A-CBL`=="POS") | 
                          (!is.na(`KMT2A-ELL`) & `KMT2A-ELL`=="POS") | 
                          (!is.na(`KMT2A-EPS15`) & `KMT2A-EPS15`=="POS") | 
                          (!is.na(`KMT2A-MLLT1`) & `KMT2A-MLLT1`=="POS") | 
                          (!is.na(`KMT2A-MLLT3`) & `KMT2A-MLLT3`=="POS") | 
                          (!is.na(`KMT2A-MLLT10`) & `KMT2A-MLLT10`=="POS") |
                          complex_karyotype == 1 |
                          monosomal_karyotype == 1 |
                          TP53 == "POS" |
                          ASXL1 == "POS" |
                          BCOR == "POS" |
                          EZH2 == "POS" |
                          RUNX1 == "POS" |
                          SF3B1 == "POS" |
                          SRSF2 == "POS" |
                          STAG2 == "POS" |
                          U2AF1 == "POS" |
                          ZRSR2 == "POS" |
                          t_6_9 == "POS" |
                          t_9_22 == "POS" | t_8_16 == "POS" | 
                          inv_3 == "POS" | monosomy7 == "POS" | del_7q == "POS" | 
                          monosomy5 == "POS" | del_5q == "POS" | 
                          monosomy17 == "POS" | del_17p == "POS", 1, 0),
      karyotype_HR = ifelse(translocation3 == 1 |
                              translocation11 == 1 |
                              # (rowSums(across(one_of(contains("t_[[:print:]]*11")))) == 1 |
                              # rowSums(across(one_of(contains("t[[:print:]]*_3")))) == 1 |
                              (str_detect(fuus, "(?i)(KAT6A|ABL1|NUP|KMT2A)") & str_detect(fuus, "(?i)(MLLT3)")) | 
                              t_6_9 == "POS" |
                              t_9_22 == "POS" | t_8_16 == "POS" | 
                              inv_3 == "POS" | monosomy7 == "POS" | del_7q == "POS" | 
                              monosomy5 == "POS" | del_5q == "POS" | 
                              monosomy17 == "POS" | del_17p == "POS", 1, 0),
      ELN1_int = ifelse((ELN1_fav == 0 | ELN1_adv == 0) & (FLT3_ITD == "POS" | t_9_11=="POS" | str_detect(fuus, "(?i)(MLLT3)") | !karyotype=="" | !mutations==""), 1, 0),
      ELN1 = ifelse(ELN1_fav == 1, "Favorable", NA),
      ELN1 = ifelse(is.na(ELN1) & ELN1_adv == 1, "Adverse", ELN1),
      ELN1 = ifelse(is.na(ELN1) & ELN1_int == 1, "Intermediate", ELN1))
      
  # these are the original classifications
  table(data$ELN1_fav);table(data$ELN1_int);table(data$ELN1_adv);table(data$ELN1)
  
  # these are the new classifications
  table(eln$ELN1_fav);table(eln$ELN1_int);table(eln$ELN1_adv);table(eln$ELN1)
  
  # save only sample identifiers and ELN classes
  eln <- eln[, c("album_id", "database_id", "henkilotunnus", "ELN1")]
  
  # rename year column to database_id
  #colnames(eln)[colnames(eln) == "year"] <- "database_id"
  
  write.csv(eln, file.path(OUTPUT_DATA_DIR, output_filename), row.names = FALSE)
}